import {parseTable,TABLE_EXAMPLE} from '../adapters/universal.js';
import {prepareImport} from '../core/import-plan.js';
import {validateEnvelope,validateSettings,DEFAULT_TIMES,conflicts,toICS} from '../core/model.js';
import {importData} from '../adapters/registry.js';import '../adapters/zfsoft.js';
import {parseSchoolPDF} from '../adapters/school-pdf.js';
import {compareImports,commitTimetableImport,undoTimetableImport,validateImportHistory,prepareUndo,currentImportState,recoverImport} from '../core/import-history.js';
import {importPersistence} from './assets.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const recoverTimetableImport=()=>recoverImport(localStorage,importPersistence);
export function setupDataTools({get,getEffective,apply,notify,openSheet}){
 let pending,pendingLabel='课表导入',busy=false;
 const school=()=>localStorage.getItem('course-compass.school.v1');
 const applySaved=()=>localStorage.getItem('course-compass.v1')?apply():true;
 function preview(value){const current=get(),plan=prepareImport(current.demo?[]:current.courses,value);pending=plan.value;pendingLabel=value.adapter||'课表备份';const changes=compareImports(current.demo?[]:current.courses,pending.courses),collision=conflicts(pending.courses);$('#import-summary').innerHTML=`<p>${E(value.adapter||'课表备份')} · <b>${plan.records.length} 条排课</b> / ${new Set(plan.records.map(c=>c.name)).size} 门课程</p><p>新增 ${changes.added} · 移除 ${changes.removed} · 完全相同 ${changes.same}<br>冲突 ${collision.length} 处。${E(plan.message)}</p>${value.settings?'':'<p>将沿用当前开学日期和作息。导入数据没有提供钟点时间，请在「学期与作息」核对。</p>'}${(value.warnings||[]).map(w=>`<p>未排入时间表：${E(w)}</p>`).join('')}`;$('#import-records').innerHTML=plan.records.map(c=>`<p><b>${E(c.name)}</b><br><small>周${c.day} · ${c.start}–${c.end}节 · ${E(c.weeks.join('、'))}周<br>${E(c.location)} · ${E(c.teacher)}</small></p>`).join('');$('#confirm-import').disabled=false;refreshHistory();openSheet('#import-sheet');}
 function receive(text){try{const value=importData(typeof text==='string'?JSON.parse(text):text);preview(value);return {ok:true,count:value.courses.length};}catch(e){notify(e.message);return {ok:false,error:e.message};}}
 window.receiveSchoolData=receive;window.onNativeExportResult=notify;window.onSchoolSyncStatus=message=>{const el=$('#native-status');if(el)el.textContent=message;};
 $('#import-file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw Error('文件超过 20 MB');notify('正在本机解析课表…');const value=/\.pdf$/i.test(file.name)||file.type==='application/pdf'?await parseSchoolPDF(new Uint8Array(await file.arrayBuffer()),notify):(/\.csv$/i.test(file.name)?parseTable(await file.text()):importData(JSON.parse(await file.text())));preview(value);}catch(e){notify(e.message);}};
 $('#confirm-import').onclick=async()=>{if(!pending||busy)return;busy=true;$('#confirm-import').disabled=true;try{const current=get(),value=validateEnvelope({...pending,settings:pending.settings||current.settings,demo:false});await commitTimetableImport({storage:localStorage,persistence:importPersistence,value,apply:applySaved,label:pendingLabel,school:school()});$('#import-sheet').close();notify('课表已更新，可在「完整备份」撤回此次导入');pending=null;await refreshHistory();}catch(e){notify(e.message);}finally{busy=false;$('#confirm-import').disabled=false;}};
 const historyPanels=[];for(const selector of ['#backup-sheet','#import-sheet']){const panel=document.createElement('section');panel.className='import-summary import-history';panel.innerHTML='<h3>最近课表更新</h3><div data-import-history-list></div><button type="button" data-import-undo disabled>撤回上次导入</button><div data-import-undo-confirm hidden><p class="sheet-tip">只恢复上次导入前的学校课程。个人安排、壁纸、留言和单次修改保留；导入后手动改过的作息也保留。</p><div class="package-actions"><button type="button" data-import-undo-cancel>取消</button><button type="button" data-import-undo-apply>确认撤回</button></div></div>';$(selector).append(panel);historyPanels.push(panel);}
 async function refreshHistory(){try{const history=validateImportHistory(await importPersistence.history());let unavailable='';try{prepareUndo(history,currentImportState(localStorage),school());}catch(e){unavailable=e.message;}
  for(const panel of historyPanels){panel.querySelector('[data-import-history-list]').innerHTML=history.entries.length?history.entries.map(e=>`<p><b>${E(e.label)}</b> · ${E(new Date(e.importedAt).toLocaleString())}<br><small>新增 ${e.summary.added} · 移除 ${e.summary.removed} · 相同 ${e.summary.same}${e.undoneAt?' · 已撤回':''}</small></p>`).join(''):'<p class="sheet-tip">确认导入后，显示最近 5 次变化，并保留最近一次导入的恢复记录。</p>';panel.querySelector('[data-import-undo]').disabled=!!unavailable;panel.querySelector('[data-import-undo]').title=unavailable;panel.querySelector('[data-import-undo-confirm]').hidden=true;}
 }catch(e){for(const panel of historyPanels)panel.querySelector('[data-import-history-list]').textContent='导入记录暂时无法读取：'+e.message;}}
 for(const panel of historyPanels)panel.addEventListener('click',async e=>{if(e.target.closest('[data-import-undo]'))panel.querySelector('[data-import-undo-confirm]').hidden=false;if(e.target.closest('[data-import-undo-cancel]'))panel.querySelector('[data-import-undo-confirm]').hidden=true;if(!e.target.closest('[data-import-undo-apply]')||busy)return;busy=true;const button=panel.querySelector('[data-import-undo-apply]');button.disabled=true;try{const restored=await undoTimetableImport({storage:localStorage,persistence:importPersistence,apply:applySaved,school:school()});pending=null;$('#import-sheet').close();notify('已撤回上次课表导入，个人设置已保留');await refreshHistory();if(!restored.schedule)location.reload();}catch(error){notify(error.message);}finally{busy=false;button.disabled=false;}});
 refreshHistory();
 function download(name,mime,text){if(window.CourseCompass?.saveFile){window.CourseCompass.saveFile(name,mime,text);return;}const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
 function term(){const {settings}=get(),f=$('#term-form');f.elements.term.value=settings.term;f.elements.startDate.value=settings.startDate;f.elements.totalWeeks.value=settings.totalWeeks;$('#period-inputs').innerHTML=settings.times.map((v,i)=>`<label>第 ${i+1} 节<input name="time${i}" value="${E(v)}" placeholder="08:20-09:05" required></label>`).join('');$('#term-error').textContent='';openSheet('#term-sheet');}
 $('#school-times').onclick=()=>{DEFAULT_TIMES.forEach((v,i)=>$('#term-form').elements['time'+i].value=v);notify('已填入截图作息，点击保存后生效');};
 $('#term-form').onsubmit=e=>{e.preventDefault();try{const fields=Object.fromEntries(new FormData(e.target)),current=get(),settings=validateSettings({...fields,times:Array.from({length:12},(_,i)=>fields['time'+i])});localStorage.setItem('course-compass.v1',JSON.stringify({version:1,courses:current.courses,settings,demo:current.demo}));apply();$('#term-sheet').close();notify('学期与作息已保存');}catch(e){$('#term-error').textContent=e.message;}};
 $('#table-example').onclick=()=>{$('#table-text').value=TABLE_EXAMPLE;};
 $('#table-parse').onclick=()=>{try{preview(parseTable($('#table-text').value));}catch(e){$('#table-error').textContent=e.message;}};
 document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;try{if(action==='table'){$('#table-error').textContent='';openSheet('#table-sheet');}if(action==='import')$('#import-file').click();if(action==='term')term();if(action==='packages')refreshHistory();if(action==='backup'){const current=get();download('课间-课表备份.json','application/json',JSON.stringify({version:1,...current},null,2));}if(action==='calendar')download('课间-课程日历.ics','text/calendar',toICS(getEffective?getEffective():get().courses,get().settings));if(action==='login')window.CourseCompass?.openPortal();if(action==='sync')window.CourseCompass?.syncPortal();}catch(error){notify(error.message);}});
 return {receive,preview,refreshHistory,undo:()=>undoTimetableImport({storage:localStorage,persistence:importPersistence,apply:applySaved,school:school()})};
}
